class Solution {
    public int minSteps(String s,String t){
        int[] difference=new int[26];
        for(char ch:s.toCharArray())difference[ch-'a']++;
        for(char ch:t.toCharArray())difference[ch-'a']--;
        int answer=0;
        for(int value:difference)answer+=Math.abs(value);
        return answer;
    }
}

code.kotlin:
class Solution {
    fun minSteps(s:String,t:String):Int{
        val difference=IntArray(26);
        for(ch in s)difference[ch-'a']++;
        for(ch in t)difference[ch-'a']--;
        return difference.sumOf{
            kotlin.math.abs(it)
        }
    }
}

